import fitz, re, os
from pathlib import Path

out_dir = Path('/root/redacted')
out_dir.mkdir(parents=True, exist_ok=True)

name_patterns_p1 = re.compile(r'(Yueqian|Zhengmian|Qinsi|Yudong|Hengfan|Jayakumar|Nikos|Helen|Yiran|Duke University|Adobe|Correspondence|@)', re.I)
arxiv_pat = re.compile(r'arXiv:\d{4}\.\d{5}', re.I)
code_pat = re.compile(r'Code and data available|github\.com/linyueqian', re.I)

name_patterns_p2 = re.compile(r'(Jiatong|Yueqian|Xinyi|Keyi|Yuning|Yuxun|Yifeng|Qin\s*Jin|Shinji|University|Institute of Technology|Renmin|Cornell|Carnegie|Duke\s*Kunshan|Georgia|cs\.cmu\.edu|@)', re.I)
footnote_p2 = re.compile(r'Equal contribution|Corresponding Author', re.I)
header_p2 = re.compile(r'Interspeech 2024|1-5 September 2024|Kos, Greece', re.I)
footer_p2 = re.compile(r'10\.21437/Interspeech', re.I)

name_patterns_p3 = re.compile(r'(Yueqian|Yuzhe|Jingyang|Yudong|Jianyi|Jingwei|Hai Li|Yiran|Duke University|Correspondence|@|Equal contribution|NSF|ARO|ICML Workshop|Copyright 2025)', re.I)


def redact_doc(in_path: Path, out_path: Path, kind: str):
    doc = fitz.open(in_path)
    for page_index, page in enumerate(doc):
        blocks = page.get_text('blocks')
        blocks_sorted = sorted(blocks, key=lambda b: (b[1], b[0]))
        in_ack = False
        for b in blocks_sorted:
            rect = fitz.Rect(b[0], b[1], b[2], b[3])
            text = b[4] or ''
            redact = False

            if kind == 'paper1':
                if page_index == 0 and (name_patterns_p1.search(text) or arxiv_pat.search(text)):
                    redact = True
                if code_pat.search(text):
                    redact = True

            elif kind == 'paper2':
                if header_p2.search(text) or footer_p2.search(text):
                    redact = True
                if page_index == 0 and (name_patterns_p2.search(text) or footnote_p2.search(text)):
                    redact = True
                # Acknowledgements section removal
                if re.search(r'Acknowledg', text, re.I):
                    in_ack = True
                if in_ack:
                    if re.search(r'\bReferences\b', text):
                        in_ack = False
                    else:
                        redact = True

            elif kind == 'paper3':
                if page_index == 0 and name_patterns_p3.search(text):
                    redact = True

            if redact:
                page.add_redact_annot(rect, fill=(0, 0, 0))

        page.apply_redactions()

    doc.save(out_path)
    doc.close()

redact_doc(Path('/root/paper1.pdf'), out_dir / 'paper1.pdf', 'paper1')
redact_doc(Path('/root/paper2.pdf'), out_dir / 'paper2.pdf', 'paper2')
redact_doc(Path('/root/paper3.pdf'), out_dir / 'paper3.pdf', 'paper3')

print('done')
PY"}
